#!/bin/bash
# Task 131-w5-acceptance-debug-checks -- meshsim sim/ WORKER5 (branch sim-w5 383b876: main with W3's increment 5).
# M1's acceptance with the debug checks real: every golden on the engine under the six option sets (ready-driven, shuffle
# seeds 1-3, instance-major, step-all), and N controllers on N threads, each a different golden, under the same six:
# N = 1, 2, 4, one per P core, every P-core thread (pinned), and every online CPU (unpinned); then make check (gcc and clang,
# debug, release, TSan). D21: no CPU list is baked in: $1 the P cores' CPUs and $2 the E cores' (e.g. "0-11" "12-15"),
# else detected from /sys (machine.inc, WORKER5; W4's sim/tools/machine.sh replaces it); the machine is recorded first.
# From an embedded kit (sim/ at 383b876). Expected ~8 min. Writes only results/131-w5-acceptance-debug-checks/. Scratch in
# /tmp, removed first and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/131-w5-acceptance-debug-checks; mkdir -p "$RES"
W=/tmp/w5-131; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "8c03916746e67b610fc2a1dde84f6148788bbb3ddc75330210af3d2ae5df6470" ] || { echo "kit sha256 mismatch (want 8c03916746e67b610fc2a1dde84f6148788bbb3ddc75330210af3d2ae5df6470)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
expand() { local out= p a b; IFS=, read -ra parts <<< "$1"; for p in "${parts[@]}"; do
  if [[ $p == *-* ]]; then a=${p%-*}; b=${p#*-}; for ((i=a; i<=b; i++)); do out+=${out:+,}$i; done; elif [ -n "$p" ]; then out+=${out:+,}$p; fi; done; echo "$out"; }
ALL_CPUS=$(expand "$(cat /sys/devices/system/cpu/online)")
if [ -n "${1:-}" ]; then P_CPUS=$(expand "$1"); elif [ -r /sys/devices/cpu_core/cpus ]; then P_CPUS=$(expand "$(cat /sys/devices/cpu_core/cpus)"); else P_CPUS=$ALL_CPUS; fi
if [ -n "${2:-}" ]; then E_CPUS=$(expand "$2"); elif [ -r /sys/devices/cpu_atom/cpus ]; then E_CPUS=$(expand "$(cat /sys/devices/cpu_atom/cpus)"); else E_CPUS=; fi
P_ONE=; for c in ${P_CPUS//,/ }; do f=$(cut -d, -f1 /sys/devices/system/cpu/cpu$c/topology/thread_siblings_list | cut -d- -f1); [ "$f" = "$c" ] && P_ONE+=${P_ONE:+,}$c; done
count() { [ -z "$1" ] && echo 0 || echo "$1" | tr ',' '\n' | wc -l; }
khz() { cat /sys/devices/system/cpu/cpu$1/cpufreq/cpuinfo_$2_freq 2>/dev/null || echo "?"; }
machine_record() {
  { echo "model:     $(lscpu | sed -n 's/^Model name: *//p' | head -1)"
    echo "sockets:   $(lscpu | sed -n 's/^Socket(s): *//p'), CPUs online $ALL_CPUS ($(count "$ALL_CPUS"))"
    local p1=${P_CPUS%%,*} e1=${E_CPUS%%,*}
    echo "P cores:   $(count "$P_ONE") cores, CPUs $P_CPUS ($(count "$P_CPUS") threads), max $(khz $p1 max) kHz, min $(khz $p1 min) kHz"
    [ -n "$E_CPUS" ] && echo "E cores:   $(count "$E_CPUS") cores, CPUs $E_CPUS, max $(khz $e1 max) kHz, min $(khz $e1 min) kHz"
    echo "governor:  $(cat /sys/devices/system/cpu/cpu0/cpufreq/scaling_governor 2>/dev/null || echo ?)"
    echo "caches:    $(lscpu | grep -E '^L[123]' | sed 's/  */ /g' | tr '\n' ';')"
    echo "memory:    $(grep MemTotal /proc/meminfo)"
    echo "kernel:    $(uname -sr)"
    echo "gcc:       $(g++ --version 2>/dev/null | head -1)"
    echo "clang:     $(clang++ --version 2>/dev/null | head -1)"
    echo "java:      $(java -version 2>&1 | head -1)"
  } > "$1"
  cat "$1"
}
FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine"; machine_record "$RES/machine.txt"
echo "lists: P $P_CPUS; one per P core $P_ONE; E ${E_CPUS:-none}; all $ALL_CPUS"
cd "$W/kit/sim" || exit 2
B=build/clang-release
sec "build (clang release)"
make -j"$(count "$ALL_CPUS")" CC_NAME=clang MODE=release $B/golden > "$RES/build.log" 2>&1 || { tail -20 "$RES/build.log"; verdict build FAIL; }
sec "1. every golden on the engine, under the six option sets"
$B/golden --engine > "$W/g.txt" 2>&1; tail -1 "$W/g.txt" | tee "$RES/engine.txt"
grep -q ' 0 differ' "$W/g.txt" && verdict "67 goldens x 6 option sets" PASS || { grep -v '^SAME' "$W/g.txt" | head -40; verdict "67 goldens x 6 option sets" FAIL; }
sec "2. N controllers on N threads, each a different golden, under the six option sets"
NP1=$(count "$P_ONE"); NP=$(count "$P_CPUS"); NALL=$(count "$ALL_CPUS")
ok=1
for n in 1 2 4 $NP1 $NP; do
  [ "$n" -le "$NP" ] || continue
  if [ "$n" -le "$NP1" ]; then c=$(echo "$P_ONE" | cut -d, -f1-"$n"); else c=$P_CPUS; fi
  $B/golden --threads "$n" --cpus "$c" > "$W/t.txt" 2>&1 || { ok=0; head -30 "$W/t.txt"; }
  echo "$(tail -1 "$W/t.txt")  [CPUs $c]" | tee -a "$RES/threads.txt"
done
$B/golden --threads "$NALL" > "$W/t.txt" 2>&1 || { ok=0; head -30 "$W/t.txt"; }
echo "$(tail -1 "$W/t.txt")  [unpinned]" | tee -a "$RES/threads.txt"
[ $ok = 1 ] && verdict "N on N threads, six option sets, every N" PASS || verdict "N on N threads, six option sets, every N" FAIL
sec "3. make check (gcc and clang; debug, release; TSan)"
make -j"$(count "$ALL_CPUS")" check > "$RES/make-check.log" 2>&1; rc=$?
grep -E '^==== |passed, [1-9]|FAIL' "$RES/make-check.log" | tail -20
[ $rc = 0 ] && grep -q 'make check: all passed' "$RES/make-check.log" && verdict "make check" PASS || { tail -30 "$RES/make-check.log"; verdict "make check" FAIL; }
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
